using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Xunit;

namespace MyApp.Evals.Tests;

public class QualityEvaluationTests
{
    private static readonly string ScenariosPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    public static IEnumerable<object[]> Scenarios =>
        LoadScenarios().Select(s => new object[] { s.Id, s });

    [Theory]
    [MemberData(nameof(Scenarios))]
    public async Task EvaluateScenario(string id, GoldenScenario scenario)
    {
        Assert.NotNull(scenario.UserMessage);

        // TODO: Wire up the agentic app endpoint and invoke with scenario.UserMessage.
        // Then evaluate the response against expected traits using the rubric.
        var response = await InvokeAgentAsync(scenario.UserMessage);

        Assert.NotNull(response);
        Assert.NotEmpty(response);
    }

    private static Task<string> InvokeAgentAsync(string userMessage)
    {
        // Placeholder: replace with actual agent invocation via AppHost.
        throw new NotImplementedException(
            "Connect to the running AppHost and send the user message to the agent endpoint.");
    }

    private static List<GoldenScenario> LoadScenarios()
    {
        var json = File.ReadAllText(ScenariosPath);
        return JsonSerializer.Deserialize<List<GoldenScenario>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;
    }
}

public record GoldenScenario
{
    public string Id { get; init; } = string.Empty;
    public string UserMessage { get; init; } = string.Empty;
    public List<string> ExpectedTraits { get; init; } = new();
}

